// 语音助手插件主代码
api.ui.onButton('btn-top', () => {
  api.toast('开始录音...');
  // 这里调用假设的录音API，完成后获取文字
  const text = '录制的文字内容';
  api.chat.sendText(text);
});
api.ui.onButton('btn-input', () => {
  api.toast('开始录音...');
  const text = '录制的文字内容';
  api.chat.sendText(text);
});
api.ui.addSettingsPanel('panel-settings', {
  title: '语音助手设置',
  items: [
    {label: '录音时长', type: 'number', default: 30},
    {label: '识别语言', type: 'select', options: ['中文', '英文'], default: '中文'}
  ]
});
